// SHARED STORAGE — uses JSONBin.io (free cloud KV, works when deployed)
// The "code" maps to a JSONBin bin ID stored in shared localStorage under that code.
// Bin IDs are stored in a public index bin so others can look them up by code.
// Encryption ensures data is private even though bins are public.
// ═══════════════════════════════════════════════════════════════════════════════

// We use a single JSONBin per pantry code.
// The bin contains: { enc: "<AES ciphertext>" }
// Bin ID is discovered by storing it in a second "index" bin keyed by code.
// Index bin ID is hardcoded (created once, public, maps code→binId).

// !! IMPORTANT: Replace with your own JSONBin master key from https://jsonbin.io
// Sign up free, go to API Keys, copy the $2a$... key
const JSONBIN_KEY = "$2a$10$GUr2ev7Dy02T4e7YDoFY4OzY8JImgzdLNcd0quwVA11DsvVx6tnmW";
const JSONBIN_INDEX_BIN = "PLACEHOLDER_INDEX_BIN_ID"; // created on first use

const JSONBIN_BASE = "https://api.jsonbin.io/v3";

async function jbGet(binId) {
  const r = await fetch(`${JSONBIN_BASE}/b/${binId}/latest`, {
    headers: { "X-Master-Key": JSONBIN_KEY, "X-Bin-Meta": "false" },
  });
  if (!r.ok) return null;
  return r.json();
}

async function jbCreate(data) {
  const r = await fetch(`${JSONBIN_BASE}/b`, {
    method: "POST",
    headers: { "Content-Type":"application/json", "X-Master-Key": JSONBIN_KEY, "X-Bin-Private":"false" },
    body: JSON.stringify(data),
  });
  if (!r.ok) return null;
  const j = await r.json();
  return j.metadata?.id || null;
}

async function jbUpdate(binId, data) {
  const r = await fetch(`${JSONBIN_BASE}/b/${binId}`, {
    method: "PUT",
    headers: { "Content-Type":"application/json", "X-Master-Key": JSONBIN_KEY },
    body: JSON.stringify(data),
  });
  return r.ok;
}

// Store pantry code → bin ID mapping in localStorage as a local cache
// and fall back to creating a new bin
function getLocalBinId(code) {
  try { return JSON.parse(localStorage.getItem(`pantry-bin-${code}`) || "null"); } catch { return null; }
}
function setLocalBinId(code, binId) {
  try { localStorage.setItem(`pantry-bin-${code}`, JSON.stringify(binId)); } catch {}
}

async function pushShared(fullCode, password, items, groceryOv, myName) {
  if (!fullCode || !password) return;
  try {
    const colonIdx = fullCode.indexOf(":");
    const shortCode = (colonIdx >= 0 ? fullCode.slice(0, colonIdx) : fullCode).toUpperCase();
    const binId     = colonIdx >= 0 ? fullCode.slice(colonIdx + 1) : null;
    if (!binId) return;
    const enc = await encryptData({ items, groceryOv, updatedAt: Date.now(), updatedBy: myName || "Someone" }, password + shortCode);
    const payload = { enc, code: shortCode, updatedAt: Date.now() };
    await jbUpdate(binId, payload);
  } catch (e) { console.error("pushShared", e); }
}

async function pullShared(fullCode, password) {
  if (!fullCode || !password) return null;
  try {
    const colonIdx = fullCode.indexOf(":");
    const shortCode = (colonIdx >= 0 ? fullCode.slice(0, colonIdx) : fullCode).toUpperCase();
    const binId     = colonIdx >= 0 ? fullCode.slice(colonIdx + 1) : null;
    if (!binId) return null;
    const data = await jbGet(binId);
    if (!data || !data.enc) return null;
    return await decryptData(data.enc, password + shortCode);
  } catch { return null; }
}
function genCode() {
  const chars = "ABCDEFGHJKLMNPQRSTUVWXYZ23456789";
  return Array.from({length:6},()=>chars[Math.floor(Math.random()*chars.length)]).join("");
}

