function daysUntil(d) { if(!d)return null; return Math.ceil((new Date(d)-new Date())/86400000); }
// threshold = days before expiry to start warning (default 30)
function expColor(days, threshold=30) {
  if(days===null)return"#555";
  if(days<0)return"#e63312";      // expired — red
  if(days<=3)return"#e63312";     // 0-3 days — red
  if(days<=7)return"#e77d00";     // 4-7 days — orange
  if(days<=14)return"#f7c800";    // 8-14 days — yellow
  if(days<=threshold)return"#f7c800"; // within warn window — yellow
  return"#4caf7d";                // safe — green
}
function expLabel(days, threshold=30) {
  if(days===null)return null;
  if(days<0)return`⚠ Expired ${Math.abs(days)}d ago`;
  if(days===0)return"⚠ Expires today!";
  if(days===1)return"⚠ Tomorrow!";
  if(days<=7)return`⚠ ${days}d left`;
  if(days<=threshold)return`📅 ${days}d left`;
  return null; // don't show label if far away
}
function stockLvl(qty) {
  if(qty<=0)return{label:"Out of stock",color:"#e63312",bar:0};
  if(qty===1)return{label:"Last one",color:"#e77d00",bar:15};
  if(qty===2)return{label:"Running low",color:"#f7c800",bar:35};
  if(qty<=4)return{label:"Moderate",color:"#85bb2f",bar:65};
  return{label:"Well stocked",color:"#4caf7d",bar:100};
}
function fmtDate(iso) {
  if(!iso)return"";
  return new Date(iso).toLocaleDateString(undefined,{day:"2-digit",month:"short",hour:"2-digit",minute:"2-digit"});
}

// ═══════════════════════════════════════════════════════════════════════════════
// AUDIO — respects sound settings passed in
// ═══════════════════════════════════════════════════════════════════════════════
function playSound(type, snd={}) {
  // snd = subset of settings relevant to sound
  if(snd.soundEnabled===false) return;
  const typeKey = type==="add"?"soundOnAdd":type==="remove"?"soundOnRemove":type==="scan"?"soundOnScan":"soundOnError";
  if(snd[typeKey]===false) return;
  const vol = ((snd.soundVolume??70)/100)*0.3; // max raw gain = 0.3
  try {
    const ctx=new(window.AudioContext||window.webkitAudioContext)();
    const g=ctx.createGain(); g.connect(ctx.destination);
    if(type==="add"){
      [0,0.12].forEach((t,i)=>{
        const o=ctx.createOscillator(); o.type="sine";
        o.frequency.setValueAtTime(520+i*180,ctx.currentTime+t);
        o.frequency.exponentialRampToValueAtTime(700+i*180,ctx.currentTime+t+0.1);
        const gn=ctx.createGain(); gn.gain.setValueAtTime(vol,ctx.currentTime+t); gn.gain.exponentialRampToValueAtTime(0.001,ctx.currentTime+t+0.18);
        o.connect(gn); gn.connect(ctx.destination); o.start(ctx.currentTime+t); o.stop(ctx.currentTime+t+0.18);
      });
    } else if(type==="remove"){
      const o=ctx.createOscillator(); o.type="sine";
      o.frequency.setValueAtTime(440,ctx.currentTime); o.frequency.exponentialRampToValueAtTime(220,ctx.currentTime+0.22);
      g.gain.setValueAtTime(vol,ctx.currentTime); g.gain.exponentialRampToValueAtTime(0.001,ctx.currentTime+0.25);
      o.connect(g); o.start(); o.stop(ctx.currentTime+0.25);
    } else if(type==="error"){
      const o=ctx.createOscillator(); o.type="square"; o.frequency.setValueAtTime(160,ctx.currentTime);
      g.gain.setValueAtTime(vol*0.5,ctx.currentTime); g.gain.exponentialRampToValueAtTime(0.001,ctx.currentTime+0.18);
      o.connect(g); o.start(); o.stop(ctx.currentTime+0.18);
    } else if(type==="scan"){
      const o=ctx.createOscillator(); o.type="sine"; o.frequency.setValueAtTime(900,ctx.currentTime);
      g.gain.setValueAtTime(vol*0.8,ctx.currentTime); g.gain.exponentialRampToValueAtTime(0.001,ctx.currentTime+0.1);
      o.connect(g); o.start(); o.stop(ctx.currentTime+0.1);
    }
  } catch{}
}

// ═══════════════════════════════════════════════════════════════════════════════
// BARCODE SCANNER
// ═══════════════════════════════════════════════════════════════════════════════
function useBarcodeScanner(onDetected, active, sndOptsRef, cooldownRef) {
  const vRef=useRef(null),stRef=useRef(null),rafRef=useRef(null),detRef=useRef(null),lastRef=useRef(null),coolRef=useRef(false);
  useEffect(()=>{
    if(!active)return; let cancelled=false;
    async function start(){
      if(!("BarcodeDetector" in window))return;
      try{
        detRef.current=new window.BarcodeDetector({formats:["ean_13","ean_8","upc_a","upc_e","code_128","code_39","qr_code"]});
        const facing = sndOptsRef?.current?.scanCamera||"environment";
        const stream=await navigator.mediaDevices.getUserMedia({video:{facingMode:facing,width:{ideal:1280},height:{ideal:720}}});
        if(cancelled){stream.getTracks().forEach(t=>t.stop());return;}
        stRef.current=stream;
        if(vRef.current){vRef.current.srcObject=stream;await vRef.current.play();}
        scan();
      }catch(e){console.error(e);}
    }
    async function scan(){
      if(cancelled||!vRef.current||!detRef.current)return;
      try{
        const codes=await detRef.current.detect(vRef.current);
        if(codes.length>0&&!coolRef.current){
          const code=codes[0].rawValue;
          if(code!==lastRef.current){
            const snd = sndOptsRef?.current||{};
            const cooldown = snd.scanCooldown??3000;
            lastRef.current=code; coolRef.current=true; playSound("scan",snd); onDetected(code);
            setTimeout(()=>{coolRef.current=false;lastRef.current=null;},cooldown);
          }
        }
      }catch{}
      rafRef.current=requestAnimationFrame(scan);
    }
    start();
    return()=>{cancelled=true;if(rafRef.current)cancelAnimationFrame(rafRef.current);if(stRef.current)stRef.current.getTracks().forEach(t=>t.stop());};
  },[active,onDetected]);
  return vRef;
}

