// CSV EXPORT / IMPORT
// ═══════════════════════════════════════════════════════════════════════════════
function itemsToCsv(items) {
  const headers = ["name","brand","category","unit","kitchenQty","storageQty","expiry","notes","barcode","kitchenThreshold","totalThreshold","expiryWarnDays","defaultGroceryQty","addedAt"];
  const esc = v => `"${String(v||"").replace(/"/g,'""')}"`;
  const rows = items.map(i => headers.map(h => esc(i[h]??"")));
  return [headers.map(h=>esc(h)), ...rows].map(r=>r.join(",")).join("\n");
}

function csvToItems(text) {
  const lines = text.trim().split("\n");
  const headers = lines[0].split(",").map(h=>h.replace(/^"|"$/g,"").replace(/""/g,'"'));
  return lines.slice(1).filter(l=>l.trim()).map(line => {
    const vals = []; let cur="", inQ=false;
    for(const ch of line+","){
      if(ch==='"'){inQ=!inQ;}
      else if(ch===","&&!inQ){vals.push(cur.replace(/""/g,'"'));cur="";}
      else cur+=ch;
    }
    const obj = {}; headers.forEach((h,i)=>obj[h]=vals[i]??"");
    return {...obj, id:uid(), kitchenQty:+obj.kitchenQty||0, storageQty:+obj.storageQty||0,
      kitchenThreshold:obj.kitchenThreshold!==""?+obj.kitchenThreshold:undefined,
      totalThreshold:obj.totalThreshold!==""?+obj.totalThreshold:undefined,
      expiryWarnDays:obj.expiryWarnDays!==""?+obj.expiryWarnDays:undefined,
      defaultGroceryQty:obj.defaultGroceryQty!==""?+obj.defaultGroceryQty:undefined,
      history:[], totalQty:(+obj.kitchenQty||0)+(+obj.storageQty||0)};
  });
}

function downloadFile(content, filename, type="text/csv") {
  const blob = new Blob([content], {type});
  const url = URL.createObjectURL(blob);
  const a = document.createElement("a"); a.href=url; a.download=filename; a.click();
  URL.revokeObjectURL(url);
}

function groceryToText(groceryList, groceryOv, defaultGroceryQty=1) {
  const byCat = {};
  groceryList.forEach(item => {
    const cat = item.category||"Other";
    const ov = groceryOv[item.id]||{};
    const qty = ov.neededQty??(item.defaultGroceryQty??defaultGroceryQty??1);
    if(!byCat[cat]) byCat[cat]=[];
    byCat[cat].push({name:item.name, brand:item.brand, unit:item.unit, qty});
  });
  return Object.entries(byCat).map(([cat,items])=>{
    const lines = items.map(i=>`${i.brand?`${i.brand} - `:""}${i.name} x${i.qty}`);
    return `${cat}:\n${lines.join("\n")}`;
  }).join("\n\n");
}

// Samsung Notes checklist format:
// Lines starting with "[ ] " become interactive checkboxes when pasted.
// Category headers are plain text lines (no prefix).
function groceryToSamsungNotes(groceryList, groceryOv, defaultGroceryQty=1) {
  const byCat = {};
  groceryList.forEach(item => {
    const cat = item.category||"Other";
    const ov = groceryOv[item.id]||{};
    const qty = ov.neededQty??(item.defaultGroceryQty??defaultGroceryQty??1);
    if(!byCat[cat]) byCat[cat]=[];
    byCat[cat].push({name:item.name, brand:item.brand, unit:item.unit, qty});
  });
  const lines = [];
  Object.entries(byCat).forEach(([cat,items],i)=>{
    if(i>0) lines.push("");
    lines.push(cat);
    items.forEach(item=>{
      const label = `${item.brand?`${item.brand} - `:""}${item.name} x${item.qty}`;
      lines.push(`[ ] ${label}`);
    });
  });
  return lines.join("\n");
}

