                      <HoldButton onPress={()=>setEditItem(p=>({...p,expiryWarnDays:(p.expiryWarnDays??settings.expiryWarnDays)+1}))} style={{...S.qtyBtn,width:26,height:26,fontSize:14}}>+</HoldButton>
