                const kStock=stockLvlS(item.kitchenQty); const sStock=stockLvlS(item.storageQty);
                const emoji=catE(item.category);
                const ov=groceryOv[item.id]||{};
                const onGrocery=ov.pinned||item.totalQty<=itemTotalThreshold(item);
