function ImportModal({onImport, onClose}) {
  const [text, setText] = useState("");
  const [mode, setMode] = useState("merge");
  const [preview, setPreview] = useState(null);
  const [err, setErr] = useState("");
  const fileRef = useRef(null);

  function handleFile(e) {
    const f = e.target.files[0]; if(!f) return;
    const r = new FileReader();
    r.onload = ev => { setText(ev.target.result); setPreview(null); setErr(""); };
    r.readAsText(f);
  }

  function handlePreview() {
    try {
      const items = csvToItems(text);
      setPreview(items); setErr("");
    } catch(e) { setErr("Invalid CSV: " + e.message); }
  }

  return (
    <div style={Mo.overlay}>
      <div style={Mo.modal}>
        <div style={Mo.header}>
          <span style={{fontFamily:"Fraunces,serif",fontSize:18,fontWeight:800}}>⬆ Import CSV</span>
          <button onClick={onClose} style={Mo.xBtn}>✕</button>
        </div>
        <p style={{fontSize:12,color:"#888",marginBottom:12}}>Import a CSV file previously exported from this app.</p>
        <input ref={fileRef} type="file" accept=".csv,text/csv" onChange={handleFile} style={{display:"none"}}/>
        <button onClick={()=>fileRef.current?.click()} style={{...S.secondaryBtn,marginBottom:10,fontSize:12}}>📂 Choose CSV file</button>
        {text&&<div style={{fontSize:11,color:"#4caf7d",marginBottom:10}}>✓ File loaded ({text.split("\n").length-1} rows)</div>}
        {err&&<div style={{fontSize:11,color:"#e63312",marginBottom:10}}>{err}</div>}
        {preview&&<div style={{fontSize:12,color:"#4caf7d",background:"#1a2a1a",padding:8,borderRadius:6,marginBottom:10}}>Preview: {preview.length} items found</div>}
        <div style={{display:"flex",gap:8,marginBottom:14}}>
          {["merge","replace"].map(m=>(
            <button key={m} onClick={()=>setMode(m)}
              style={{flex:1,padding:"8px",borderRadius:8,border:`1px solid ${mode===m?"#4caf7d":"#2a2a22"}`,
                background:mode===m?"#1a2a1a":"transparent",color:mode===m?"#4caf7d":"#666",fontFamily:"DM Mono,monospace",fontSize:12,cursor:"pointer"}}>
              {m==="merge"?"Merge (keep existing)":"Replace all"}
            </button>
          ))}
        </div>
        <div style={{display:"flex",gap:8,justifyContent:"flex-end"}}>
          <button onClick={onClose} style={Mo.cancelBtn}>Cancel</button>
          {!preview?<button onClick={handlePreview} disabled={!text} style={{...S.primaryBtn,opacity:text?1:0.4}}>Preview</button>
            :<button onClick={()=>onImport(preview,mode)} style={S.primaryBtn}>Import {preview.length} items</button>}
        </div>
      </div>
    </div>
  );
}

// Hold-to-repeat button — fires once on click, then repeats while held
function HoldButton({ onPress, children, style, disabled }) {
  const timerRef    = useRef(null);
  const intervalRef = useRef(null);
  const firedRef    = useRef(false); // track whether hold-repeat already fired

  function start(e) {
    e.preventDefault();
    if (disabled) return;
    firedRef.current = false;
    // Fire once immediately on press
    onPress();
    firedRef.current = true;
    // After 400ms hold, start repeating
    timerRef.current = setTimeout(() => {
      intervalRef.current = setInterval(() => { onPress(); }, 80);
    }, 400);
  }

  function stop(e) {
    e.preventDefault();
    clearTimeout(timerRef.current);
    clearInterval(intervalRef.current);
    firedRef.current = false;
  }

  return (
    <button
      onPointerDown={start}
      onPointerUp={stop}
      onPointerLeave={stop}
      onPointerCancel={stop}
      // Never let click fire — all logic is in pointer events
      onClick={e => e.preventDefault()}
      disabled={disabled}
      style={{...style, userSelect:"none", WebkitUserSelect:"none", touchAction:"none"}}
    >{children}</button>
  );
}

